246	    private Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next, String reason) {
247	        Claim claim = lockedClaim(sheetId, id);
248	        switch (next) {
249	            case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
250	            case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
251	            case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
252	            default -> {
253	            }
254	        }
255	        RollupService.Snapshot before = rollup.snapshot(sheetId);
256	        String tail = "";
257	        // settling is the step from OPEN; a pending claim is settled by approving it
258	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
259	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
260	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
261	            throw new ResponseStatusException(HttpStatus.CONFLICT,
262	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
263	        }
264	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
265	            throw new ResponseStatusException(HttpStatus.CONFLICT,
266	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
267	        }
268	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
269	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
270	        }
271	        if (next == ClaimStatus.SETTLED && by.equals(claim.getEditedBy())) {
272	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who last edited a claim cannot settle it.");
273	        }
274	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
275	            refuseVoidOfSettled(by, sheetId, claim);
276	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
277	            tail = " reversed=" + text(claim.getSettledDue());
278	        }
279	        if (next == ClaimStatus.VOID) {
280	            String voidReason = voidReasons.refuseUnlessListed(sheetId, reason);
281	            claim.setVoidReason(voidReason);
282	            if (voidReason != null) {
283	                tail += " reason=" + voidReason;
284	            }
285	        }
286	        if (next == ClaimStatus.OPEN) {
287	            refuseWithoutNote(sheetId, claim);
288	            refuseOverPeriodCap(sheetId, claim);
289	            number(sheetId, claim);
290	            claim.setOpenedBy(by);
291	        }
292	        Person person = person(sheetId, claim.getPersonId());
293	        String event = switch (next) {
294	            case OPEN -> "CLAIM_OPENED";
295	            case SETTLED -> "CLAIM_SETTLED";
296	            case VOID -> "CLAIM_VOIDED";
297	            case DRAFT, PENDING, DELETED -> throw new IllegalStateException();
298	        };
299	        if (next == ClaimStatus.SETTLED) {
300	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
301	            // force on the claim's date, with the late charge it has gained by today, and at least the floor in force
302	            // on its date; with none it stays live
303	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
304	                    : rateFigure(sheetId, person, claim);
305	            BigDecimal fixed = liveDue(figure, claim, person, sheets.load(sheetId), true);
306	            refuseWithoutProof(sheetId, claim, fixed);
307	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
308	                next = ClaimStatus.PENDING;
309	                event = "CLAIM_PENDING";
310	            } else {
311	                claim.setSettledDue(fixed);
312	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
313	            }
314	        }
315	        claim.setStatus(next);
316	        logStatus(by, sheetId, person, claim);
317	        Claim saved = claims.saveAndFlush(claim);
318	        audit.recordOnCommit(record(event, by, person, saved) + tail);
319	        if (next == ClaimStatus.SETTLED) {
320	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
321	        }
322	        rollup.recordChanges(by, sheetId, before);
323	        return saved;
324	    }
325	
326	    /**
327	     * Deletes a DRAFT claim: it is DELETED, counts nowhere and can no longer be edited, opened or voided. Refused
328	     * for a claim in any other status, one another user's editor holds, and in a closed period.
329	     */
330	    @Transactional
331	    public Claim delete(String by, String sheetId, Long id) {
332	        Claim claim = lockedClaim(sheetId, id);
333	        if (claim.getStatus() != ClaimStatus.DRAFT) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a DRAFT claim can be deleted.");
335	        }
336	        refuseLockedByOther(by, claim);
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        Person person = person(sheetId, claim.getPersonId());
339	        claim.setStatus(ClaimStatus.DELETED);
340	        claim.setLockedBy(null);
341	        logStatus(by, sheetId, person, claim);
342	        Claim saved = claims.saveAndFlush(claim);
343	        audit.recordOnCommit(record("CLAIM_DELETED", by, person, saved));
344	        rollup.recordChanges(by, sheetId, before);
345	        return saved;
346	    }
347	
348	    /**
349	     * Restores a DELETED claim to a DRAFT again. Refused for a claim that is not DELETED, unless the sheet's today is
350	     * the one it was deleted on, and in a closed period.
351	     */
352	    @Transactional
353	    public Claim restore(String by, String sheetId, Long id) {
354	        Claim claim = lockedClaim(sheetId, id);
355	        if (claim.getStatus() != ClaimStatus.DELETED) {
356	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a DELETED claim can be restored.");
357	        }
358	        LocalDate today = sheets.load(sheetId).getToday();
359	        LocalDate deletedOn = claim.deletedOn();
360	        if (deletedOn == null ? today != null : !deletedOn.equals(today)) {
361	            throw new ResponseStatusException(HttpStatus.CONFLICT,
362	                    "A claim can only be restored on the day it was deleted.");
363	        }
364	        RollupService.Snapshot before = rollup.snapshot(sheetId);
365	        Person person = person(sheetId, claim.getPersonId());
366	        claim.setStatus(ClaimStatus.DRAFT);
367	        logStatus(by, sheetId, person, claim);
368	        Claim saved = claims.saveAndFlush(claim);
369	        audit.recordOnCommit(record("CLAIM_RESTORED", by, person, saved));
370	        rollup.recordChanges(by, sheetId, before);
371	        return saved;
372	    }
373	
374	    /**
375	     * Defers an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts
376	     * in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that is
377	     * not OPEN, a date not after today, and in a closed period.
378	     */
379	    @Transactional
380	    public Claim defer(String by, String sheetId, Long id, LocalDate until) {
381	        Claim claim = lockedClaim(sheetId, id);
382	        if (claim.getStatus() != ClaimStatus.OPEN) {
383	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
384	        }
385	        LocalDate today = sheets.load(sheetId).getToday();
386	        if (until == null || (today != null && !until.isAfter(today))) {
387	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
388	                    "A claim can only be deferred to a date after the sheet's today.");
389	        }
390	        RollupService.Snapshot before = rollup.snapshot(sheetId);
391	        claim.setDeferredUntil(until, today);
392	        Claim saved = claims.saveAndFlush(claim);
393	        audit.recordOnCommit(record("CLAIM_DEFERRED", by, person(sheetId, saved.getPersonId()), saved) + " until="
394	                + until);
395	        rollup.recordChanges(by, sheetId, before);
396	        return saved;
397	    }
398	
399	    /**
400	     * Writes a reminder for an OPEN or PENDING claim, which shows the sheet's today as its reminded date. Refused for
401	     * a claim in any other status and one already reminded on the sheet's today; a reminder changes none of the
402	     * claim's figures, so one whose due-by falls in a closed period may still be reminded.
403	     */
404	    @Transactional
405	    public Claim remind(String by, String sheetId, Long id) {
406	        sheets.lock(sheetId);
407	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
408	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
409	        if (!claim.getStatus().isOpen()) {
410	            throw new ResponseStatusException(HttpStatus.CONFLICT,
411	                    "A " + claim.getStatus() + " claim cannot be reminded.");
412	        }
413	        LocalDate today = sheets.load(sheetId).getToday();
414	        if (today != null && today.equals(claim.getRemindedOn())) {
415	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today.");
416	        }
417	        claim.setRemindedOn(today);
418	        Claim saved = claims.saveAndFlush(claim);
419	        audit.recordOnCommit(record("REMIND", by, person(sheetId, saved.getPersonId()), saved));
420	        return saved;
421	    }
422	
423	    /** Adds a comment to the claim, by the user on the sheet's today. Refused for a blank comment. */
424	    @Transactional
425	    public Claim comment(String by, String sheetId, Long id, String text) {
426	        String stripped = text == null ? "" : text.strip();
427	        if (stripped.isEmpty()) {
428	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A comment cannot be empty.");
429	        }
430	        sheets.lock(sheetId);
431	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
432	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
433	        claim.comment(by, sheets.load(sheetId).getToday(), stripped);
434	        Claim saved = claims.saveAndFlush(claim);
435	        audit.recordOnCommit(record("COMMENT_ADDED", by, person(sheetId, saved.getPersonId()), saved) + " text="
436	                + stripped);
437	        return saved;
438	    }
439	
440	    /**
441	     * Adds a line to a DRAFT claim: its amount becomes the sum of its lines' quantities times unit amounts. Adding a
442	     * line edits the claim. Refused for a blank label, a quantity below 1, a unit amount below 0.00 or with more than
443	     * two decimals, a claim that is not a DRAFT, one another user's editor holds, and in a closed period.
444	     */
445	    @Transactional
446	    public Claim addLine(String by, String sheetId, Long id, String label, Integer qty, BigDecimal unit) {
447	        String stripped = label == null ? "" : label.strip();
448	        if (stripped.isEmpty()) {
449	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A line needs a label.");
450	        }
451	        if (qty == null || qty < 1) {
452	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
453	                    "A line's quantity is a whole number of at least 1.");
454	        }
455	        if (unit == null || unit.signum() < 0 || unit.stripTrailingZeros().scale() > 2) {
456	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
457	                    "A line's unit amount is 0.00 or more, with up to two decimals.");
458	        }
459	        Claim claim = lockedClaim(sheetId, id);
460	        if (claim.getStatus() != ClaimStatus.DRAFT) {
461	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can take a line.");
462	        }
463	        refuseLockedByOther(by, claim);
464	        RollupService.Snapshot before = rollup.snapshot(sheetId);
465	        BigDecimal scaledUnit = unit.setScale(2, RoundingMode.UNNECESSARY);
466	        claim.addLine(stripped, qty, scaledUnit);
467	        claim.setEditedBy(by);
468	        Claim saved = claims.saveAndFlush(claim);
469	        audit.recordOnCommit(record("CLAIM_LINE_ADDED", by, person(sheetId, saved.getPersonId()), saved) + " label="
470	                + stripped + " qty=" + qty + " unit=" + scaledUnit.toPlainString());
471	        rollup.recordChanges(by, sheetId, before);
472	        return saved;
473	    }
474	
475	    /**
476	     * Raises the claim's proofs count by one. Refused for a SETTLED, VOID or DELETED claim, and in a closed period.
477	     */
478	    @Transactional
479	    public Claim addProof(String by, String sheetId, Long id) {
480	        Claim claim = lockedClaim(sheetId, id);
481	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
482	                || claim.getStatus() == ClaimStatus.DELETED) {
483	            throw new ResponseStatusException(HttpStatus.CONFLICT,
484	                    "A " + claim.getStatus() + " claim cannot take a proof.");
485	        }
486	        claim.addProof();
487	        Claim saved = claims.saveAndFlush(claim);
488	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", by, person(sheetId, saved.getPersonId()), saved)
489	                + " proofs=" + saved.getProofs());
490	        return saved;
491	    }
492	
493	    /**
494	     * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
495	     * force on the claim's date (its person's grade's then when one is set, else the sheet's) and the claim has no
496	     * proof; an n/a due is within any threshold.
497	     */
498	    private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
499	        String grade = person(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
500	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
501	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
502	            throw new ResponseStatusException(HttpStatus.CONFLICT,
503	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
504	        }
505	    }
506	
507	    /**
508	     * Refuses opening the claim when its note is empty and its due is above the note threshold in force on its date;
509	     * an n/a due is within any threshold.
510	     */
511	    /**
512	     * Refuses opening a claim whose due-by falls in a period with a cap when its person already has that many OPEN or
513	     * PENDING claims due by a date in it. The sheet stays locked until the transaction ends, so two opens are counted
514	     * in turn.
515	     */
516	    private void refuseOverPeriodCap(String sheetId, Claim claim) {
517	        Period period = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
518	                claim.getDueBy(), claim.getDueBy()).orElse(null);
519	        if (period == null || period.getCap() == null) {
520	            return;
521	        }
522	        long held = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
523	                .filter(c -> !c.getId().equals(claim.getId()))
524	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
525	                .filter(c -> period.contains(c.getDueBy()))
526	                .count();
527	        if (held >= period.getCap()) {
528	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
529	                    + " open claims in period " + period.getName() + ".");
530	        }
531	    }
532	
533	    private void refuseWithoutNote(String sheetId, Claim claim) {
534	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
535	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
536	            return;
537	        }
538	        BigDecimal due = due(sheetId, person(sheetId, claim.getPersonId()), claim);
539	        if (due != null && due.compareTo(threshold) > 0) {
540	            throw new ResponseStatusException(HttpStatus.CONFLICT,
541	                    "A claim with a due above " + threshold.toPlainString() + " needs a note first.");
542	        }
543	    }
544	
545	    /**
546	     * A steward approves a pending claim: it is settled, its due fixed at the live figure it shows now. Refused
547	     * unless it is pending, unless the user is a steward, for the user who opened it or last edited it, and in a
548	     * closed period.
549	     */
550	    @Transactional
551	    public Claim approve(String by, String sheetId, Long id) {
552	        Claim claim = pendingClaim(by, sheetId, id);
553	        if (by.equals(claim.getOpenedBy())) {
554	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot approve it.");
555	        }
556	        if (by.equals(claim.getEditedBy())) {
557	            throw new ResponseStatusException(HttpStatus.CONFLICT,
558	                    "The user who last edited a claim cannot approve it.");
559	        }
560	        RollupService.Snapshot before = rollup.snapshot(sheetId);
561	        Person person = person(sheetId, claim.getPersonId());
562	        BigDecimal fixed = due(sheetId, person, claim);
563	        refuseWithoutProof(sheetId, claim, fixed);
564	        claim.setSettledDue(fixed);
565	        claim.setStatus(ClaimStatus.SETTLED);
566	        logStatus(by, sheetId, person, claim);
567	        Claim saved = claims.saveAndFlush(claim);
568	        audit.recordOnCommit(record("CLAIM_APPROVED", by, person, saved) + " due="
569	                + (fixed == null ? "n/a" : fixed.toPlainString()));
570	        watches.notifyWatchers(by, sheetId, person, saved.getNumber());
571	        rollup.recordChanges(by, sheetId, before);
572	        return saved;
573	    }
574	
575	    /**
576	     * A steward re-settles a settled claim: its due is frozen again at the figure it would have today as an open
577	     * claim bound by no statement (today's rates, grades and floor, with the late charge it has gained by today; a
578	     * correction gains none). Refused unless the user is a steward, unless it is settled, and in a closed period.
579	     */
580	    @Transactional
581	    public Claim resettle(String by, String sheetId, Long id) {
582	        if (!settings.isSteward(sheetId, by)) {
583	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
584	        }
585	        Claim claim = lockedClaim(sheetId, id);
586	        if (claim.getStatus() != ClaimStatus.SETTLED) {
587	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
588	        }
589	        RollupService.Snapshot before = rollup.snapshot(sheetId);
590	        Person person = person(sheetId, claim.getPersonId());
591	        BigDecimal old = claim.getSettledDue();
592	        BigDecimal fixed = liveDue(rateFigure(sheetId, person, claim), claim, person, sheets.load(sheetId), true);
593	        claim.setSettledDue(fixed);
594	        logStatus(by, sheetId, person, claim);
595	        Claim saved = claims.saveAndFlush(claim);
596	        audit.recordOnCommit(record("CLAIM_RESETTLED", by, person, saved) + " old=" + text(old) + " new="
597	                + text(fixed));
598	        watches.notifyWatchers(by, sheetId, person, saved.getNumber());
599	        rollup.recordChanges(by, sheetId, before);
600	        return saved;
601	    }
602	
603	    /**
604	     * Numbers the claims a bulk settle settled (or made PENDING) as the sheet's next batch, and returns its number.
605	     * Refused with nothing to number: a bulk settle that settles none is no batch.
606	     */
607	    @Transactional
608	    public int numberSettleBatch(String sheetId, List<Long> ids) {
609	        if (ids.isEmpty()) {
610	            throw new IllegalArgumentException("A batch needs at least one claim.");
611	        }
612	        int batch = sheets.nextSettleBatch(sheetId);
613	        for (Claim claim : claims.findAllById(ids)) {
614	            claim.setSettleBatch(batch);
615	        }
616	        return batch;
617	    }
618	
619	    /**
620	     * A steward rejects a pending claim with a reason: it is open again, bound again by its person's last statement
621	     * when that included it. Refused unless it is pending, unless the user is a steward, without a reason, and in a
622	     * closed period.
623	     */
624	    @Transactional
625	    public Claim reject(String by, String sheetId, Long id, String reason) {
626	        String why = reason == null ? "" : reason.strip();
627	        if (why.isEmpty()) {
628	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A rejection needs a reason.");
629	        }
630	        Claim claim = pendingClaim(by, sheetId, id);
631	        RollupService.Snapshot before = rollup.snapshot(sheetId);
632	        claim.setStatus(ClaimStatus.OPEN);
633	        // open again, it is no longer settled by the batch that made it pending
634	        claim.setSettleBatch(null);
635	        logStatus(by, sheetId, person(sheetId, claim.getPersonId()), claim);
636	        Claim saved = claims.saveAndFlush(claim);
637	        audit.recordOnCommit(record("CLAIM_REJECTED", by, person(sheetId, saved.getPersonId()), saved)
638	                + " reason=" + why);
639	        rollup.recordChanges(by, sheetId, before);
640	        return saved;
641	    }
642	
643	    /**
644	     * A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person of the sheet. It keeps its date,
645	     * takes the next number in the sequence it would be numbered in now (a draft, having none, gets none) and never gives its old one again,
646	     * loses any figure a statement bound it to (it is live again until its new person's next statement), and is
647	     * listed as its new person's newest claim. Refused unless the user's role may reassign, for a settled or voided claim,
648	     * to the person it is already with, in a closed period, and when it is dated after the new person's retirement.
649	     */

