687	     * A steward re-dates an OPEN or PENDING claim. Its due-by, and so its period and number, stay as they were fixed
688	     * and a figure a statement bound it to stays bound; its rounding (unless a correction) follows the new date.
689	     * Refused unless the user is a steward, for a claim that is not OPEN or PENDING, for a claim whose due-by falls
690	     * in a closed period, and for a new date after the person's retirement.
691	     */
692	    @Transactional
693	    public Claim redate(String by, String sheetId, Long id, LocalDate date) {
694	        if (!settings.isSteward(sheetId, by)) {
695	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
696	        }
697	        Claim claim = lockedClaim(sheetId, id);
698	        if (!claim.getStatus().isOpen()) {
699	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be re-dated.");
700	        }
701	        Person person = person(sheetId, claim.getPersonId());
702	        refuseAfterRetirement(person, date);
703	        RollupService.Snapshot before = rollup.snapshot(sheetId);
704	        LocalDate old = claim.getDate();
705	        claim.setDate(date);
706	        if (!claim.isCorrection()) {
707	            claim.setRoundsOn(date);
708	        }
709	        Claim saved = claims.saveAndFlush(claim);
710	        audit.recordOnCommit(record("CLAIM_REDATED", by, person, saved) + " old=" + old + " new=" + date);
711	        rollup.recordChanges(by, sheetId, before);
712	        return saved;
713	    }
