715	    /** An OPEN claim after a split, and the new OPEN claim split off it. */
716	    public record Split(Claim original, Claim split) {
717	    }
718	
719	    /**
720	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
721	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
722	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
723	     * number, and a late entry when the original is, is listed as its person's newest. Refused unless the user's
724	     * role may open a claim, for a claim that is not OPEN or is deferred, for an amount out of range, and when the
725	     * original's due-by falls in a closed period (the new claim's own due-by is not judged).
726	     */
727	    @Transactional
728	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
729	        settings.refuseUnlessMay(sheetId, by, "open");
730	        Claim claim = lockedClaim(sheetId, id);
731	        if (claim.getStatus() != ClaimStatus.OPEN) {
732	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
733	        }
734	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
735	            throw new ResponseStatusException(HttpStatus.CONFLICT,
736	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
737	        }
738	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
739	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
740	                    "The amount split off must be more than 0.00 and less than the claim's.");
741	        }
742	        RollupService.Snapshot before = rollup.snapshot(sheetId);
743	        Person person = person(sheetId, claim.getPersonId());
744	        claim.setAmount(claim.getAmount().subtract(scaled(amount)));
745	        claim.unbind();
746	        Claim original = claims.saveAndFlush(claim);
747	        Claim part = new Claim(sheetId, claim.getPersonId(), scaled(amount), claim.getDate(), claim.getNote());
748	        part.setRoundsOn(claim.getRoundsOn());
749	        int terms = termsFor(sheetId, person, claim.getDate());
750	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
751	        part.setTerms(terms);
752	        part.setSplitFrom(claim.getNumber());
753	        part.setTags(claim.getTags());
754	        // a split is judged by the original alone: the part is a late entry when the original is
755	        part.setLateEntry(claim.isLateEntry());
756	        part.setStatus(ClaimStatus.OPEN);
757	        number(sheetId, part);
758	        part.setOpenedBy(by);
759	        logStatus(by, sheetId, person, part);
760	        Claim added = claims.saveAndFlush(part);
761	        audit.recordOnCommit(record("CLAIM_SPLIT", by, person, original) + " into=" + added.getNumber());
762	        audit.recordOnCommit(record("CLAIM_OPENED", by, person, added));
763	        rollup.recordChanges(by, sheetId, before);
764	        return new Split(original, added);
765	    }
