801	    /** The claim, locked; refused when its due-by falls in a closed period. */
802	    private Claim lockedClaim(String sheetId, Long id) {
803	        // the sheet is locked before the claim, in the order a period closing takes them
804	        sheets.lock(sheetId);
805	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
806	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
