811	    /**
812	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
813	     * after it, the next in the sequence of the period the claim's due-by falls in (X for none), else FY<year>-n, the
814	     * next in the fiscal year the due-by falls in, counted across the sheet's tree.
815	     * The sheet is locked, so two claims opened at once never get the same one.
816	     */
817	    private void number(String sheetId, Claim claim) {
818	        if (!numbersByPeriod(sheetId)) {
819	            LocalDate placedOn = claim.getDueBy() != null ? claim.getDueBy() : claim.getDate();
820	            int year = sheets.load(sheetId).fiscalYearOf(placedOn);
821	            claim.setNumber("FY" + year + "-" + sheets.nextFiscalClaimNumber(sheetId, year));
822	            return;
823	        }
824	        String sequence = sequenceOn(sheetId, claim.getDueBy());
825	        Long last = claims.lastInSequence(sheetId, sequence);
826	        claim.numberIn(sequence, last == null ? 1 : last + 1);
827	    }
