874	    /**
875	     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
876	     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
877	     */
878	    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
879	        Sheet sheet = sheets.load(sheetId);
880	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
881	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
882	                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
