889	    /**
890	     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
891	     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
892	     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
893	     */
894	    @Transactional(readOnly = true)
895	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
896	        Sheet sheet = sheets.load(sheetId);
897	        int count = 0;
898	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
899	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
900	            if (!claim.getStatus().isOpen() || claim.getSettledDue() != null || claim.isBound()) {
901	                continue;
902	            }
903	            Person person = person(sheetId, claim.getPersonId());
904	            if (!grade.equals(person.gradeOn(claim.getDate()))) {
905	                continue;
906	            }
907	            BigDecimal current = due(sheetId, person, claim);
908	            BigDecimal figure = dueOn(claim.getAmount(), pct, sheet.roundingOn(claim.getRoundsOn()));
909	            BigDecimal next = liveDue(figure, claim, person, sheet, true);
910	            BigDecimal before = current == null ? BigDecimal.ZERO : current;
911	            if (current == null || before.compareTo(next) != 0) {
912	                count++;
913	                diff = diff.add(next.subtract(before));
914	            }
915	        }
916	        return new RatePreview(count, diff.setScale(2));
917	    }
