919	    /**
920	     * The figure of the claim: its settled due, else the one a statement bound it to (not while it is pending), else
921	     * its rate figure. A statement binds this figure, under the late charge and the floor.
922	     */
923	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
924	        if (claim.getSettledDue() != null) {
925	            return claim.getSettledDue();
926	        }
927	        return claim.isBound() ? claim.getStatedDue() : rateFigure(sheetId, person, claim);
928	    }
