930	    /**
931	     * The due the claim shows and totals: its settled due as frozen, else its live due on its figure (the late charge
932	     * only while it is open or pending).
933	     */
934	    public BigDecimal due(String sheetId, Person person, Claim claim) {
935	        BigDecimal figure = figure(sheetId, person, claim);
936	        return claim.getSettledDue() != null ? figure
937	                : liveDue(figure, claim, person, sheets.load(sheetId), claim.getStatus().isOpen());
938	    }
