940	    /**
941	     * The live due of a claim on its (unfloored) figure: the greater of the floor in force on its date and the figure
942	     * plus the late charge it has gained (when charged); a correction has neither floor nor charge. Null (n/a) for an
943	     * n/a figure.
944	     */
945	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Person person, Sheet sheet, boolean charged) {
946	        if (figure == null || claim.isCorrection()) {
947	            return figure;
948	        }
949	        BigDecimal due = charged ? withLateCharge(figure, claim, person, sheet) : figure;
950	        return sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
951	    }
952	
953	    /**
954	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
955	     * late-from: its due-by plus its grace) by the sheet's today: for each such boundary (its late-from plus 30, 60,
956	     * 90 ... days), the sheet's late
957	     * percent in force on that boundary date of the figure plus the charges of the boundaries before it (it
958	     * compounds), rounded like its due; a boundary whose percent is 0.00 adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
959	     * sheet's today and its policy date.
960	     */
961	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Person person, Sheet sheet) {
962	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
963	            return figure;
964	        }
965	        LocalDate lateFrom = lateFrom(claim, person, sheet);
966	        long overdue = ChronoUnit.DAYS.between(lateFrom, sheet.getToday());
967	        long periods = overdue > 0 ? overdue / 30 : 0;
968	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
969	        BigDecimal due = figure;
970	        for (long k = 1; k <= periods; k++) {
971	            BigDecimal latePct = sheet.latePctOn(lateFrom.plusDays(30 * k));
972	            if (latePct.signum() != 0) {
973	                due = due.add(dueOn(due, latePct, rounding));
974	            }
975	        }
976	        return due;
977	    }
978	
979	    /**
980	     * The date after which the claim is overdue: its due-by plus the grace days the sheet has in force on the claim's
981	     * date for its person's grade in force on that date (none: its due-by). Its late charge's 30-day boundaries count
982	     * from it; the due-by the claim shows is unchanged.
983	     */
984	    public static LocalDate lateFrom(Claim claim, Person person, Sheet sheet) {
985	        if (claim.getDueBy() == null || person == null || sheet == null) {
986	            return claim.getDueBy();
987	        }
988	        return claim.getDueBy().plusDays(sheet.graceOn(person.gradeOn(claim.getDate()), claim.getDate()));
989	    }
