992	     * Refuses a change to a claim due by the date when a closed period contains it. The sheet stays locked until
993	     * the transaction ends, so a period closing at the same moment is checked in turn.
994	     */
995	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
996	        sheets.lock(sheetId);
997	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
998	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim's due-by falls in a closed period.");
999	        }
