1002	    /**
1003	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
1004	     * claim of the person, else refused; null for any other claim.
1005	     */
1006	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
1007	        if (amount.signum() >= 0) {
1008	            return null;
1009	        }
1010	        corrects = corrects == null ? null : corrects.strip();
1011	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
1012	                ClaimStatus.SETTLED)) {
