1052	    /**
1053	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
1054	     * negative amount rounds like its positive).
1055	     */
1056	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
1057	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
