1092	    /**
1093	     * The external reference a claim is to carry: stripped, or null when blank. Refused when another claim of the
1094	     * sheet than the one excluded (null for none) carries it, comparing without regard to case.
1095	     */
1096	    private String refOf(String sheetId, String ref, Long excluded) {
1097	        String stripped = ref == null ? "" : ref.strip();
1098	        if (stripped.isEmpty()) {
1099	            return null;
1100	        }
1101	        if (claims.refInUse(sheetId, stripped, excluded)) {
1102	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1103	                    "The reference " + stripped + " is already used on the sheet.");
1104	        }
1105	        return stripped;
