1112	    /** Every tag ever used on a claim of the sheet, sorted. */
1113	    @Transactional(readOnly = true)
1114	    public List<String> tags(String sheetId) {
1115	        return tags.findBySheetIdOrderByTagAsc(sheetId).stream().map(ClaimTag::getTag).toList();
1116	    }
1117	
1118	    /** A claim's stored tags as a list, sorted; empty for none. */
1119	    public static List<String> tagList(String stored) {
1120	        return stored == null || stored.isEmpty() ? List.of() : List.of(stored.split(","));
1121	    }
1122	
1123	    /** The tags a claim or person is to carry: each trimmed and lower-cased, repeats and blanks dropped, sorted and comma separated; null for none. */
1124	    public static String tagsOf(String tagged) {
1125	        if (tagged == null) {
1126	            return null;
1127	        }
1128	        TreeSet<String> each = new TreeSet<>();
1129	        Arrays.stream(tagged.split(",")).map(t -> t.strip().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
1130	                .forEach(each::add);
1131	        if (each.stream().anyMatch(t -> t.length() > 140)) {
1132	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A tag is at most 140 characters.");
1133	        }
1134	        return each.isEmpty() ? null : String.join(",", each);
1135	    }
