1137	    /** Keeps each of the tags as used on the sheet. */
1138	    private void keepTags(String sheetId, String stored) {
1139	        for (String tag : tagList(stored)) {
1140	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) {
1141	                tags.saveAndFlush(new ClaimTag(sheetId, tag));
1142	            }
1143	        }
1144	    }
