669	  // The order the list is shown in; it belongs to the screen (each user's own), so loading a sheet keeps it.
670	  // Only the screen is sorted: positions, rollups and every action in list order are unaffected.
671	  protected readonly sortKey = signal('added');
672	  protected readonly shownPeople = computed(() => {
673	    const shown = this.showRetired() ? this.people() : this.people().filter((p) => p.retiredFrom === null);
674	    const key = this.sortKey();
675	    if (key === 'added') return shown;
676	    const due = this.dueBy();
677	    const sortValue = (p: Person): string | number | null => {
678	      if (key === 'name') return p.name.toLowerCase();
679	      if (key === 'grade') return this.gradeToday(p);
680	      const d = due.get(p.id);
681	      return d == null ? null : Number(d);
682	    };
683	    const keyed = shown.map((p) => ({ p, v: sortValue(p) }));
684	    // Array.prototype.sort is stable, so equal keys keep list order; n/a goes last.
685	    keyed.sort((a, b) => {
686	      if (a.v === null || b.v === null) return a.v === null ? (b.v === null ? 0 : 1) : -1;
687	      return a.v < b.v ? -1 : a.v > b.v ? 1 : 0;
688	    });
689	    return keyed.map((k) => k.p);
690	  });
