764	  // For every tag ever used on the sheet (those the store keeps and those on the claims and people now), sorted: the
765	  // due of the claims counted live that carry it, or whose person carries it, once each, skipping n/a; a claim with
766	  // two tags counts in both.
767	  protected readonly tagDueTotals = computed(() => {
768	    const all = new Set([
769	      ...this.usedTags(),
770	      ...this.claims().flatMap((c) => c.tags),
771	      ...this.people().flatMap((p) => p.tags),
772	    ]);
773	    const personTags = new Map(this.people().map((p) => [p.id, p.tags]));
774	    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
775	    const rates = this.rates.rates();
776	    const floor = this.settings.floor();
777	    const late = this.settings.lateness();
778	    const dues = new Map<string, (string | null)[]>();
779	    for (const c of this.liveClaims()) {
780	      const carried = new Set([...c.tags, ...(personTags.get(c.personId) ?? [])]);
781	      if (carried.size === 0) continue;
782	      const own = grades.get(c.personId) ?? [];
783	      const due = dueOf(c, rates.get(gradeOn(own, c.date)) ?? [], floor, late, graceOf(c, own, late));
784	      for (const t of carried) dues.set(t, [...(dues.get(t) ?? []), due]);
785	    }
786	    return [...all]
787	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
788	      .map((tag) => ({ tag, dueTotal: sumSkippingNa(dues.get(tag) ?? []) }));
789	  });
790	  // For every month (yyyy-mm) any claim on the sheet is dated in, sorted: the due of the claims counted live dated
