793	    const all = new Set(this.claims().map((c) => c.date.slice(0, 7)));
794	    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
795	    const rates = this.rates.rates();
796	    const floor = this.settings.floor();
797	    const late = this.settings.lateness();
798	    const dues = new Map<string, (string | null)[]>();
799	    for (const c of this.liveClaims()) {
800	      const own = grades.get(c.personId) ?? [];
801	      const month = c.date.slice(0, 7);
802	      dues.set(month, [...(dues.get(month) ?? []), dueOf(c, rates.get(gradeOn(own, c.date)) ?? [], floor, late, graceOf(c, own, late))]);
803	    }
804	    return [...all]
805	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
806	      .map((month) => ({ month, dueTotal: sumSkippingNa(dues.get(month) ?? []) }));
