852	    const retiredFrom = new Map(this.people().map((p) => [p.id, p.retiredFrom]));
853	    // a person whose retirement date the sheet's today has reached holds every claim, as a hold would
854	    const held = (c: Claim) => {
855	      const from = retiredFrom.get(c.personId) ?? null;
