872	  // Each person's due-total: the sum of their counted claims' figures, each settled one's frozen figure or
873	  // the one a statement bound it to, or its live due, skipping n/a. With no rate in force today for their grade
874	  // today nor for the grade of any counted claim's date it is null (n/a), unless a counted claim has a figure (a
875	  // settled or stated one, or one dated within a rate that has since ended). This is before the sheet's cap.
876	  private readonly uncappedDueBy = computed(() => {
877	    const by = new Map<number, string | null>();
878	    const current = this.rates.current();
879	    const rates = this.rates.rates();
880	    const floor = this.settings.floor();
881	    const late = this.settings.lateness();
882	    for (const p of this.people()) {
883	      const counted = this.liveBy().get(p.id) ?? [];
884	      // the grades whose rate today decides n/a: the one in force today and each counted claim's
885	      const grades = [this.gradeToday(p), ...counted.map((c) => gradeOn(p.grades, c.date))];
886	      const dues = counted.map((c) => dueOf(c, rates.get(gradeOn(p.grades, c.date)) ?? [], floor, late, graceOf(c, p.grades, late)));
887	      if (!grades.some((g) => current.has(g)) && dues.every((d) => d === null)) {
888	        by.set(p.id, null);
889	        continue;
890	      }
891	      by.set(p.id, sumSkippingNa(dues));
892	    }
893	    return by;
894	  });
895	  // Each person's settled-total and open-total: the figures of their counted settled claims (frozen, corrections
896	  // included) and of their counted open and pending claims, each skipping n/a. Together they make the due-total
897	  // before the cap.
898	  protected readonly splitBy = computed(() => {
899	    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
900	    const rates = this.rates.rates();
901	    const floor = this.settings.floor();
902	    const late = this.settings.lateness();
903	    const by = new Map<number, { settled: string; open: string }>();
904	    for (const [id, list] of this.liveBy()) {
905	      const own = grades.get(id) ?? [];
906	      const due = (c: Claim) => dueOf(c, rates.get(gradeOn(own, c.date)) ?? [], floor, late, graceOf(c, own, late));
907	      by.set(id, {
908	        settled: sumSkippingNa(list.filter((c) => c.status === 'SETTLED').map(due)),
909	        open: sumSkippingNa(list.filter(isOpen).map(due)),
910	      });
911	    }
912	    return by;
913	  });
