// A clerk settling a claim whose due is above the clerk limit makes it PENDING, for a steward to approve (SETTLED)
// or reject (OPEN again). A deleted DRAFT is DELETED, counts nowhere, and on the day it was deleted can be restored.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

type ClaimAction = 'open' | 'settle' | 'resettle' | 'approve' | 'reject' | 'void' | 'delete' | 'restore';

/** Only open, pending and settled claims count toward what is claimed and due. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/**
 * The status the claim had at the end of the day, as its log records it: the last line logged on or before it (a
 * line with no date counts as before any day); null when the claim was added after it. A claim with no log has its
 * status now.
 */
export function statusAtEndOf(c: Pick<Claim, 'status' | 'log'>, day: string): ClaimStatus | null {
  if (c.log.length === 0) return c.status;
  let then: ClaimStatus | null = null;
  for (const line of c.log) if (line.on === null || line.on <= day) then = line.status;
  return then;
}

/** Whether the claim is open: OPEN or PENDING. An open claim goes overdue and bears the late charge. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether the person's last statement binds the claim's figure: not while it is pending, which shows it live. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** Whether the claim is a correction: one with a negative amount. */
export function isCorrection(c: Claim): boolean {
  return c.amount.startsWith('-');
}

/**
 * Whether the claim's live figures round half up: when the date its rounding follows is before the policy date
 * (the sheet's today when the setting is blank); else they round half to even.
 */
export function roundsHalfUp(c: Claim, policyDate: string | null): boolean {
  return policyDate !== null && c.roundsOn < policyDate;
}

/**
 * The figure of a claim: its settled due, else the one a statement bound it to (not while it is pending), else its
 * rate figure at the rate in force on its date (no floor), rounded as the policy date decides for it; null (n/a)
 * with none.
 */
export function figureOf(c: Claim, rates: readonly RateView[], policyDate: string | null): string | null {
  if (c.settledDue !== null) return c.settledDue;
  if (isBound(c)) return c.statedDue;
  return dueOn(c.amount, rateOn(rates, c.date), roundsHalfUp(c, policyDate));
}

/** Whether the claim keeps a figure whatever the rates: a settled or bound one with a figure. */
export function keepsFigure(c: Claim): boolean {
  return c.settledDue !== null || (isBound(c) && c.statedDue !== null);
}

/** Whether the claim was deferred until a date after the sheet's today, whatever its status: as the row shows it. */
export function deferredUntilAfter(c: Claim, today: string | null): boolean {
  return c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/**
 * Whether a claim is deferred: OPEN and deferred until a date after the sheet's today. Until today reaches that
 * date it counts in no total, is not overdue and cannot be settled; from then on it is an OPEN claim like any other.
 */
export function deferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** Whether a claim makes its person active: open (or pending) and dated within the 30 days up to and including today. */
export function activeOn(c: Claim, today: string | null): boolean {
  return isOpen(c) && today !== null && plusDays(today, -29) <= c.date && c.date <= today;
}

/**
 * The date after which a claim is overdue: its due-by plus the grace days (those its person's grade in force on its
 * date has in force on that date). Its late charge's 30-day boundaries count from it; the due-by shown is unchanged.
 */
export function lateFrom(c: Claim, grace: number): string {
  return grace > 0 ? plusDays(c.dueBy, grace) : c.dueBy;
}

/** Whether a claim is overdue: open (or pending), not deferred, and its due-by plus its grace is before the sheet's today. */
export function overdue(c: Claim, today: string | null, grace = 0): boolean {
  return isOpen(c) && today !== null && !deferred(c, today) && lateFrom(c, grace) < today;
}

/** The grace days of the claim: those its person's grade in force on its date has in force on that date. */
export function graceOf(c: Claim, grades: readonly DatedGrade[], late: Lateness): number {
  return late.grace(gradeOn(grades, c.date), c.date);
}

/** The floor in force on a date. */
export type FloorOn = (date: string) => string;

/**
 * What the late charge follows: the sheet's today and the late percent in force on a date; and the policy
 * date in force (the sheet's today when the setting is blank), which decides how a claim's live figures round.
 */
export interface Lateness {
  today: string | null;
  latePct: (date: string) => string;
  policyDate: string | null;
  /** The grace days the grade has in force on a date; 0 with none. */
  grace: (grade: string | null, date: string) => number;
}

/** The whole days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  const utc = (d: string) => {
    const [y, m, day] = d.split('-').map(Number);
    return Date.UTC(y, m - 1, day);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/** The date (yyyy-mm-dd) the given whole days after another. */
export function plusDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/**
 * The due a claim shows and totals: a settled claim's frozen due; else its live due, the greater of the floor in
 * force on its date and its figure plus the late charge: for an overdue claim, for each full 30 days it is overdue,
 * the late percent in force on that boundary date (its due-by plus its grace, plus 30, 60, 90 ... days) of the figure
 * plus the charges of the boundaries before it (it compounds), rounded like the claim; a boundary whose percent is 0.00 adds nothing. Neither the charge nor the floor is bound by a
 * statement. A correction has neither.
 */
export function dueOf(c: Claim, rates: readonly RateView[], floor: FloorOn, late: Lateness, grace = 0): string | null {
  const figure = figureOf(c, rates, late.policyDate);
  if (figure === null || c.settledDue !== null || isCorrection(c)) return figure;
  if (!overdue(c, late.today, grace)) return atLeast(figure, floor(c.date));
  const from = lateFrom(c, grace);
  const periods = Math.floor(daysBetween(from, late.today!) / 30);
  const halfUp = roundsHalfUp(c, late.policyDate);
  let due = figure;
  for (let k = 1; k <= periods; k++) {
    due = sumSkippingNa([due, dueOn(due, late.latePct(plusDays(from, 30 * k)), halfUp)]);
  }
  return atLeast(due, floor(c.date));
}

const CLOSED = 'That claim is due by a date in a closed period, so it cannot change.';
const LOCKED = 'Another user is editing this claim; try again once they are done.';
const LINED = 'This claim has lines, so its amount is the sum of its lines and cannot be typed.';

// The line being typed for a claim, as typed.
interface LineFields {
  label: string;
  qty: string;
  unit: string;
}

/** Whether two amounts with up to two decimals are the same amount. */
function sameAmount(a: string, b: string): boolean {
  return Math.round(Number(a) * 100) === Math.round(Number(b) * 100);
}

export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** A claim form's amount: a negative one is a correction. */
const SIGNED_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * The sum of the counted claims' amounts, leaving out claims that correct another, with two decimals; added in whole
 * cents so nothing drifts.
 */
export function claimedTotal(claims: readonly Claim[]): string {
  const cents = claims.filter(c => counts(c) && !c.corrects).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

export interface DatedGrade {
  grade: string;
  from: string | null;
}

/** The grade in force on the date: the one with the latest from-date on or before it; '' with none. */
export function gradeOn(grades: readonly DatedGrade[], date: string | null): string {
  let best: DatedGrade | undefined;
  for (const g of grades) {
    if (g.from !== null && (date === null || g.from > date)) continue;
    if (!best || (g.from !== null && (best.from === null || g.from > best.from))) best = g;
  }
  return best?.grade ?? '';
}

const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/** Whole cents of a two-decimal value. */
function cents(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const c = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -c : c;
}

/**
 * The due on an amount at a rate (both two-decimal strings): amount times rate divided by 100,
 * rounded half to even (or half up, when asked) to two decimals; null (n/a) when there is no rate.
 * Worked in whole numbers so nothing drifts.
 */
export function dueOn(amount: string, pct: string | undefined, halfUp = false): string | null {
  if (pct === undefined) return null;
  const product = cents(amount) * cents(pct);
  // rounded on the size, so a negative amount (a correction) rounds like its positive
  const size = product < 0n ? -product : product;
  let due = size / 10000n;
  const rest = size % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || due % 2n === 1n))) due += 1n;
  return formatCents(product < 0n ? -due : due);
}

/** The two-decimal value, raised to the floor when it is below it. */
export function atLeast(value: string, floor: string): string {
  return cents(value) < cents(floor) ? formatCents(cents(floor)) : value;
}

/** The two-decimal value held to the cap when it is above it; n/a, or no cap (null), leaves it as it is. */
export function atMost(value: string | null, cap: string | null): string | null {
  return value !== null && cap !== null && cents(value) > cents(cap) ? formatCents(cents(cap)) : value;
}

/** What the two-decimal value is above the cap: 0.00 when it is not, is n/a, or there is no cap (null). */
export function excessOver(value: string | null, cap: string | null): string {
  return value !== null && cap !== null && cents(value) > cents(cap) ? formatCents(cents(value) - cents(cap)) : '0.00';
}

/** The sum of two-decimal values, skipping n/a. */
export function sumSkippingNa(values: readonly (string | null)[]): string {
  return formatCents(values.reduce((sum, v) => (v === null ? sum : sum + cents(v)), 0n));
}

/** One two-decimal figure minus another, as a two-decimal figure with a minus sign when negative. */
export function difference(value: string, minus: string): string {
  return formatCents(cents(value) - cents(minus));
}

/**
 * 100.00 split equally into the given number of two-decimal shares, each rounded half to even, with the remainder
 * (100.00 minus the shares added up) given to the first.
 */
export function equalShares(count: number): string[] {
  if (count <= 0) return [];
  const n = BigInt(count);
  let share = 10000n / n;
  const rest = 10000n % n;
  if (rest * 2n > n || (rest * 2n === n && share % 2n === 1n)) share += 1n;
  return Array.from({ length: count }, (_, i) => formatCents(i === 0 ? 10000n - share * (n - 1n) : share));
}

/** The sum of each two-decimal figure times its two-decimal share divided by 100, rounded half to even. */
export function sharedSum(parts: readonly { figure: string; share: string }[]): string {
  const product = parts.reduce((sum, p) => sum + cents(p.figure) * cents(p.share), 0n);
  const size = product < 0n ? -product : product;
  let total = size / 10000n;
  const rest = size % 10000n;
  if (rest > 5000n || (rest === 5000n && total % 2n === 1n)) total += 1n;
  return formatCents(product < 0n ? -total : total);
}

/**
 * The sheet-total of two-decimal figures, skipping n/a: with three or more figures, the single highest and the
 * single lowest are left out.
 */
export function trimmedSum(values: readonly (string | null)[]): string {
  const figures = values.filter((v): v is string => v !== null).map(cents);
  let sum = figures.reduce((total, c) => total + c, 0n);
  if (figures.length >= 3) {
    const max = figures.reduce((a, b) => (b > a ? b : a));
    const min = figures.reduce((a, b) => (b < a ? b : a));
    sum -= max + min;
  }
  return formatCents(sum);
}

/**
 * The percent of the rate in force on the date among one grade's rates: the one with the latest
 * from-date on or before it, a rate with no from-date applying from the beginning of time;
 * undefined (n/a) when none applies yet, or when the date is past that one's to-date.
 */
export function rateOn(rates: readonly RateView[], date: string | null): string | undefined {
  let best: RateView | undefined;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (!best || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  if (best?.to && date !== null && date > best.to) return undefined;

/**
 * The fiscal year the date falls in, named FY<yyyy> by the calendar year its first day falls in: fiscal years start on
 * the first of the start month (1 to 12).
 */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** The period whose dates contain the date; undefined when none does. */
export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** Whether a closed period contains the date. */
export function inClosedPeriod(periods: readonly PeriodView[], date: string): boolean {
  return periodOn(periods, date)?.closed ?? false;
}

/**
 * The person's due-total for each period, by period id: a closed one's figure fixed for them when it was closed
 * (0.00 for a person added since), else the figures now of their claims due by a date in it that counted at the end of its
 * last day, skipping n/a.
 */
export function personPeriodDueTotals(
  periods: readonly PeriodView[],
  personId: number,
  figures: readonly DatedFigure[],
): Map<number, string> {
  const by = new Map<number, (string | null)[]>();
  for (const p of periods) by.set(p.id, []);
  for (const f of figures) {
    if (f.personId !== personId) continue;
    const p = periodOn(periods, f.dueBy);
    if (p && countedAtEndOf(f, p.to)) by.get(p.id)?.push(f.figure);
  }
  return new Map(
    periods.map((p) => [
      p.id,
      p.closed || p.softClosed ? (p.closedPersonTotals[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
    ]),
  );
}

/** Each period's due-total, by period id: the sum of the people's due-totals for it. */
export function periodDueTotals(
  periods: readonly PeriodView[],
  figures: readonly DatedFigure[],
): Map<number, string> {
  // everyone with a figure for some period: a counted claim, or one fixed when a period closed
  const people = new Set(figures.map((f) => f.personId));
  for (const p of periods) for (const id of Object.keys(p.closedPersonTotals)) people.add(Number(id));
  const each = [...people].map((id) => personPeriodDueTotals(periods, id, figures));
  return new Map(periods.map((p) => [p.id, sumSkippingNa(each.map((m) => m.get(p.id) ?? null))]));
}

